# Emerging Memory

## What is useful but still unsettled?

This folder holds useful ideas, findings and reasoning that are not accepted yet.

## Axioms

- At each #KeepInMind refresh, check these Entries and save useful candidate material before it is lost. "Nothing useful to save" is a valid result. Do not turn raw activity into Memory.
- Keep each record's source, uncertainty and scope visible when they affect later use.
- Refine material while its validity, use or final destination is unsettled.
- When something is accepted, move the durable result to the source that should define it. Before moving or pruning rejected or replaced material, keep its useful outcomes and reasoning.
- Revisit repeated or stale material and decide whether to consolidate, promote, move or prune it.

## Entries

- [Structured reasoning, investigation, or comparison that is useful but not accepted truth](analysis/_analysis.md) - #Extension #Memory #Analysis #Contextual #Candidate
- [Future possibilities, experiments, open questions, and options to explore later](ideas/_ideas.md) - #Extension #Memory #Idea #Exploration #Contextual #Candidate
- [Concrete occurrences or patterns noticed in evidence that may become reusable learning](observations/_observations.md) - #Extension #Memory #Observation #AgentLearning #Contextual #Candidate
import { createGame, MOVES_MAX, ELAPSED_MAX_MS } from './game.ts';
import { parseBoardCode } from './deck.ts';
import { isValidDealName } from './deal-name.ts';
import {
  hasExactKeys,
  isJsonObject,
  isNonnegativeSafeInteger,
  isWithinBytes,
  parseJson,
} from './saved-format.ts';
import { readMatched, readSelection } from './snapshot-selection.ts';
import { SelectionKind } from './selection.ts';
import type { GameState } from './game.ts';

export const SNAPSHOT_VERSION = 1;
export const NAMED_SNAPSHOT_VERSION = 2;
export const SNAPSHOT_MAX_BYTES = 65_536;
export const SNAPSHOT_KEYS = [
  'version',
  'boardCode',
  'matched',
  'selection',
  'moves',
  'elapsedMs',
  'started',
] as const;
export const NAMED_SNAPSHOT_KEYS = [...SNAPSHOT_KEYS, 'name'] as const;

export function encodeSnapshot(state: GameState): string {
  const version = state.name ? NAMED_SNAPSHOT_VERSION : SNAPSHOT_VERSION;
  const snapshot = {
    version,
    ...(state.name ? { name: state.name } : {}),
    boardCode: state.boardCode,
    matched: [...state.matched].sort((left, right) => left - right),
    // Active time keeps its fractions in play. Export writes whole milliseconds, and rounding
    // pending time up keeps a mismatch at 1ms or more.
    selection:
      state.selection.kind === SelectionKind.mismatch
        ? { ...state.selection, remainingMs: Math.ceil(state.selection.remainingMs) }
        : state.selection,
    moves: state.moves,
    elapsedMs: Math.floor(state.elapsedMs),
    started: state.started,
  };
  return JSON.stringify(snapshot, null, 2);
}

export function decodeSnapshot(text: string): GameState | null {
  const value = isWithinBytes(text, SNAPSHOT_MAX_BYTES) ? parseJson(text) : undefined;
  if (!isJsonObject(value)) return null;
  let name = '';
  if (value.version === NAMED_SNAPSHOT_VERSION) {
    if (
      !hasExactKeys(value, NAMED_SNAPSHOT_KEYS) ||
      !isValidDealName(value.name) ||
      value.name.length === 0
    )
      return null;
    name = value.name;
  } else if (value.version !== SNAPSHOT_VERSION || !hasExactKeys(value, SNAPSHOT_KEYS)) return null;
  if (typeof value.boardCode !== 'string' || !parseBoardCode(value.boardCode)) return null;
  if (
    !isNonnegativeSafeInteger(value.moves) ||
    value.moves > MOVES_MAX ||
    !isNonnegativeSafeInteger(value.elapsedMs) ||
    value.elapsedMs > ELAPSED_MAX_MS ||
    typeof value.started !== 'boolean'
  )
    return null;
  const initial = createGame(value.boardCode);
  const matched = readMatched(value.matched, initial);
  if (!matched) return null;
  const selection = readSelection(value.selection, initial, matched);
  if (!selection) return null;
  const state: GameState = {
    ...initial,
    name,
    matched,
    selection,
    moves: value.moves,
    elapsedMs: value.elapsedMs,
    started: value.started,
  };
  const minimumMoves = matched.length / 2 + (selection.kind === SelectionKind.mismatch ? 1 : 0);
  if (state.moves < minimumMoves) return null;
  if (
    !state.started &&
    (state.moves !== 0 ||
      state.elapsedMs !== 0 ||
      matched.length !== 0 ||
      selection.kind !== SelectionKind.closed)
  )
    return null;
  if (state.started && state.moves === 0 && selection.kind === SelectionKind.closed) return null;
  return state;
}
export const DEAL_NAME_MAX_LENGTH = 40;

export function isValidDealName(value: unknown): value is string {
  return (
    typeof value === 'string' &&
    value.length <= DEAL_NAME_MAX_LENGTH &&
    !value.includes('\r') &&
    !value.includes('\n')
  );
}
import assert from 'node:assert/strict';
import { test } from 'vitest';
import { createGame } from './game.ts';
import { DEAL_NAME_MAX_LENGTH, isValidDealName } from './deal-name.ts';
import {
  decodeSnapshot,
  encodeSnapshot,
  NAMED_SNAPSHOT_KEYS,
  NAMED_SNAPSHOT_VERSION,
  SNAPSHOT_MAX_BYTES,
} from './snapshot.ts';
import { EXAMPLE_CODE } from './game.fixture.ts';

test('named progress exports version 2 and restores its name', () => {
  const name = '  Café 🎲  ';
  const state = { ...createGame(EXAMPLE_CODE), name };
  const encoded: unknown = JSON.parse(encodeSnapshot(state));
  assert.ok(encoded && typeof encoded === 'object');
  assert.deepEqual(Object.keys(encoded).sort(), [...NAMED_SNAPSHOT_KEYS].sort());
  assert.equal('version' in encoded && encoded.version, NAMED_SNAPSHOT_VERSION);
  assert.deepEqual(decodeSnapshot(encodeSnapshot(state)), state);
});

test('version 1 and version 2 snapshots accept property order from pasted JSON', () => {
  const unnamed =
    '{"boardCode":"np1-4-1","matched":[0,11],"selection":{"kind":"mismatch","first":1,"second":2,"remainingMs":300},"moves":2,"elapsedMs":1500,"started":true,"version":1}';
  assert.equal(decodeSnapshot(unnamed)?.name, '');
  const named =
    '{"name":"Café","boardCode":"np1-4-1","matched":[],"selection":{"kind":"one","index":2},"moves":0,"elapsedMs":0,"started":true,"version":2}';
  assert.equal(decodeSnapshot(named)?.name, 'Café');
});

test('deal names preserve spaces and accept exactly 40 UTF-16 code units', () => {
  const maximumAscii = 'x'.repeat(40);
  const maximumAstral = '😀'.repeat(20);
  assert.equal(DEAL_NAME_MAX_LENGTH, 40);
  assert.equal(isValidDealName(maximumAscii), true);
  assert.equal(decodeSnapshot(named(maximumAscii))?.name, maximumAscii);
  assert.equal(maximumAstral.length, 40);
  assert.equal(decodeSnapshot(named(maximumAstral))?.name, maximumAstral);
  assert.equal(isValidDealName(' café '), true);
  assert.equal(isValidDealName('x'.repeat(41)), false);
  assert.equal(isValidDealName('😀'.repeat(21)), false);
  assert.equal(decodeSnapshot(named('😀'.repeat(21))), null);
  assert.equal(isValidDealName('line\nfeed'), false);
  assert.equal(decodeSnapshot(named('line\nfeed')), null);
  assert.equal(isValidDealName('carriage\rreturn'), false);
  assert.equal(decodeSnapshot(named('carriage\rreturn')), null);
  assert.equal(decodeSnapshot(named('')), null, 'version 2 requires a nonempty name');
  assert.equal(decodeSnapshot(namedValue(42)), null, 'name must be a string');
});

test('snapshot versions reject mixed fields, unknown fields, and missing fields', () => {
  const valid = {
    version: NAMED_SNAPSHOT_VERSION,
    name: 'Run',
    boardCode: EXAMPLE_CODE,
    matched: [],
    selection: { kind: 'one', index: 2 },
    moves: 0,
    elapsedMs: 0,
    started: true,
  };
  assert.equal(decodeSnapshot(JSON.stringify({ ...valid, extra: true })), null);
  assert.equal(decodeSnapshot(JSON.stringify({ ...valid, version: 3 })), null);
  assert.equal(decodeSnapshot(JSON.stringify({ ...valid, version: 1 })), null);
  const { name: _name, ...withoutName } = valid;
  assert.equal(decodeSnapshot(JSON.stringify(withoutName)), null);
  assert.equal(decodeSnapshot(JSON.stringify({ ...valid, name: undefined })), null);
  assert.equal(decodeSnapshot(JSON.stringify({ ...valid, version: 1, name: 'Run' })), null);
});

test('named snapshots enforce the UTF-8 byte limit', () => {
  const text = named(' Café ');
  const padding = SNAPSHOT_MAX_BYTES - new TextEncoder().encode(text).byteLength;
  assert.ok(padding > 0);
  assert.ok(decodeSnapshot(text + ' '.repeat(padding)));
  assert.equal(decodeSnapshot(text + ' '.repeat(padding + 1)), null);
});

function named(name: string): string {
  return namedValue(name);
}

function namedValue(name: unknown): string {
  return JSON.stringify({
    version: NAMED_SNAPSHOT_VERSION,
    name,
    boardCode: EXAMPLE_CODE,
    matched: [],
    selection: { kind: 'one', index: 2 },
    moves: 0,
    elapsedMs: 0,
    started: true,
  });
}
"}

tools.description:
Run JavaScript code to orchestrate/compose tool calls
- Evaluates the provided JavaScript code in a fresh V8 isolate as an async module.
- All nested tools are available on the global `tools` object, for example `await tools.exec_command(...)`. Tool names are exposed as normalized JavaScript identifiers, for example `await tools.mcp__ologs__get_profile(...)`.
- Nested tool methods take either a string or an object as their input argument.
- Nested tools return either an object or a string, based on the description.
- Runs raw JavaScript -- no Node, no file system, no network access, no console.
- Accepts raw JavaScript source text, not JSON, quoted strings, or markdown code fences.
- You may optionally start the tool input with a first-line pragma like `// @exec: {"yield_time_ms": 10000, "max_output_tokens": 1000}`.
- `yield_time_ms` asks `exec` to yield early if the script is still running. Defaults to 30000 ms.
- `max_output_tokens` sets the token budget for direct `exec` results. Defaults to 10000 tokens.
- When the JS code is fully evaluated, the isolate's lifetime ends and unawaited promises are silently discarded.

- Global helpers:
- `exit()`: Immediately ends the current script successfully (like an early return from the top level).
- `text(value: string | number | boolean | undefined | null)`: Appends a text item. Non-string values are stringified with `JSON.stringify(...)` when possible.
- `image(imageUrlOrItem: string | { image_url: string; detail?: "auto" | "low" | "high" | "original" | null } | ImageContent, detail?: "auto" | "low" | "high" | "original" | null)`: Appends an image item. `image_url` should be a base64-encoded `data:` URL. To forward an MCP tool image, pass an individual `ImageContent` block from `result.content`, for example `image(result.content[0])`. MCP image blocks may request detail with `_meta: { "codex/imageDetail": "original" }`. When provided, the second `detail` argument overrides any detail embedded in the first argument.
- `audio(audioUrlOrItem: string | { audio_url: string } | AudioContent)`: Appends an audio item. `audio_url` should be a base64-encoded `data:` URL. To forward an MCP tool audio block, pass an individual `AudioContent` block from `result.content`, for example `audio(result.content[0])`.
- `generatedImage(result: { image_url: string; output_hint?: string })`: Appends an image-generation result and its optional output hint. HTTP(S) URLs are not supported.
- `store(key: string, value: any)`: stores a serializable value under a string key for later `exec` calls in the same session.
- `load(key: string)`: returns the stored value for a string key, or `undefined` if it is missing.
- `notify(value: string | number | boolean | undefined | null)`: immediately injects an extra `custom_tool_call_output` for the current `exec` call. Values are stringified like `text(...)`.
- `setTimeout(callback: () => void, delayMs?: number)`: schedules a callback to run later and returns a timeout id. Pending timeouts do not keep `exec` alive by themselves; await an explicit promise if you need to wait for one.
- `clearTimeout(timeoutId?: number)`: cancels a timeout created by `setTimeout`.
- `ALL_TOOLS`: metadata for the enabled nested tools as `{ name, description }` entries.
- `yield_control()`: yields the accumulated output to the model immediately while the script keeps running.

Some deferred nested tools may be omitted from this description. They are still available on the global `tools` object and listed in `ALL_TOOLS`.
To find one, filter `ALL_TOOLS` by `name` and `description`.

Tool availability can change between calls.

Shared MCP Types:
```ts
type Role = "user" | "assistant";
type MetaObject = Record<string, unknown>;
type Annotations = {
  audience?: Role[];
  priority?: number;
  lastModified?: string;
};
type Icon = {
  src: string;
  mimeType?: string;
  sizes?: string[];
  theme?: "light" | "dark";
};
type TextResourceContents = {
  uri: string;
  mimeType?: string;
  _meta?: MetaObject;
  text: string;
};
type BlobResourceContents = {
  uri: string;
  mimeType?: string;
  _meta?: MetaObject;
  blob: string;
};
type TextContent = {
  type: "text";
  text: string;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type ImageContent = {
  type: "image";
  data: string;
  mimeType: string;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type AudioContent = {
  type: "audio";
  data: string;
  mimeType: string;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type ResourceLink = {
  icons?: Icon[];
  name: string;
  title?: string;
  uri: string;
  description?: string;
  mimeType?: string;
  annotations?: Annotations;
  size?: number;
  _meta?: MetaObject;
  type: "resource_link";
};
type EmbeddedResource = {
  type: "resource";
  resource: TextResourceContents | BlobResourceContents;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type ContentBlock =
  | TextContent
  | ImageContent
  | AudioContent
  | ResourceLink
  | EmbeddedResource;
type CallToolResult<TStructured = { [key: string]: unknown }> = {
  _meta?: MetaObject;
  content: ContentBlock[];
  isError?: boolean;
  structuredContent?: TStructured;
  [key: string]: unknown;
};
```

### `apply_patch`
The `apply_patch` tool can be used to edit files. This is a FREEFORM tool, so do not wrap the patch in JSON.

exec tool declaration:
```ts
declare const tools: { apply_patch(input: string): Promise<unknown>; };
```

### `create_goal`
Create a goal only when explicitly requested by the user or system/developer instructions; do not infer goals from ordinary tasks.
Set token_budget only when an explicit token budget is requested. Fails if an unfinished goal exists; use update_goal only for status.

exec tool declaration:
```ts
declare const tools: { create_goal(args: {
  // Required. The concrete objective to start pursuing. This starts a new active goal when no goal exists or replaces the current goal when it is complete.
  objective: string;
  // Positive token budget for the new goal. Omit unless explicitly requested.
  token_budget?: number;
}): Promise<unknown>; };
```

### `exec_command`
Runs a command in a PTY, returning output or a session ID for ongoing interaction.

exec tool declaration:
```ts
declare const tools: { exec_command(args: {
  // Shell command to execute.
  cmd: string;
  // User-facing approval question for `require_escalated`; omit otherwise.
  justification?: string;
  // True runs the shell with -l/-i semantics; false disables them. Defaults to true.
  login?: boolean;
  // Output token budget. Defaults to 10000 tokens; larger requests may be capped by policy.
  max_output_tokens?: number;
  // Reusable approval prefix for `cmd`, only with `sandbox_permissions: "require_escalated"`; for example ["git", "pull"].
  prefix_rule?: Array<string>;
  // Per-command sandbox override. Defaults to `use_default`; use `require_escalated` for unsandboxed execution.
  sandbox_permissions?: "use_default" | "require_escalated";
  // Shell binary to launch. Defaults to the user's default shell.
  shell?: string;
  // True allocates a PTY for the command; false or omitted uses plain pipes.
  tty?: boolean;
  // Working directory for the command. Defaults to the turn cwd.
  workdir?: string;
  // Wait before yielding output. Defaults to 10000 ms; effective range is 250-30000 ms.
  yield_time_ms?: number;
}): Promise<{
  // Chunk identifier included when the response reports one.
  chunk_id?: string;
  // Process exit code when the command finished during this call.
  exit_code?: number;
  // Approximate token count before output truncation.
  original_token_count?: number;
  // Command output text, possibly truncated.
  output: string;
  // Session identifier to pass to write_stdin when the process is still running.
  session_id?: number;
  // Elapsed wall time spent waiting for output in seconds.
  wall_time_seconds: number;
}>; };
```

### `get_goal`
Get the current goal for this thread, including status, budgets, token and elapsed-time usage, and remaining token budget.

exec tool declaration:
```ts
declare const tools: { get_goal(args: {}): Promise<unknown>; };
```

### `list_mcp_resource_templates`
Lists resource templates provided by MCP servers. Parameterized resource templates allow servers to share data that takes parameters and provides context to language models, such as files, database schemas, or application-specific information. Prefer resource templates over web search when possible.

exec tool declaration:
```ts
declare const tools: { list_mcp_resource_templates(args: {
  // Opaque cursor from a previous list_mcp_resource_templates call; omit for the first page.
  cursor?: string;
  // MCP server name. Omit to list resource templates from every configured server.
  server?: string;
}): Promise<unknown>; };
```

### `list_mcp_resources`
Lists resources provided by MCP servers. Resources allow servers to share data that provides context to language models, such as files, database schemas, or application-specific information. Prefer resources over web search when possible.

exec tool declaration:
```ts
declare const tools: { list_mcp_resources(args: {
  // Opaque cursor from a previous list_mcp_resources call; omit for the first page.
  cursor?: string;
  // MCP server name. Omit to list resources from every configured server.
  server?: string;
